const rows = $items('Read Jobs', 0).map((item) => item.json);
if (!rows.length) {
  throw new Error('Queue pick: Read Jobs returned 0 rows');
}
const excludedCompanies = (() => {
  try {
    return $('Load Exclude Companies').all()
      .map((item) => String(item.json.Company || item.json.company || '').trim())
      .filter(Boolean);
  } catch (e) {
    return [];
  }
})();
const policy = $('Check Apply Policy').first().json;
const pickLimit = Math.max(0, Number(policy.dailyPickLimit ?? policy.maxAttempts ?? 20));
const batchId = `${$execution.id}-apply`;
const runId = String($execution.id);
const triggeredAt = new Date().toISOString();

const response = await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
  method: 'POST',
  url: 'http://job-application-agent:3000/queue/pick',
  headers: { 'Content-Type': 'application/json' },
  body: { rows, excludedCompanies, pickLimit },
  json: true,
});

const selected = Array.isArray(response.selected) ? response.selected : [];
return selected.map((row) => ({
  json: {
    ...row,
    _applyRun: {
      batchId,
      runId,
      triggeredAt,
      pickedTech: response.pickedTech,
      pickedMarketing: response.pickedMarketing,
      eligible: response.eligible,
    },
  },
}));

const src = $('One Job').item.json;
const res = $json || {};
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Jerusalem' });
if (res.status === 'budget_reached') {
  return [{
    json: {
      row_number: src.row_number,
      company: src.Company,
      role: src.Role,
      Status: 'New',
      'Applied Date': src['Applied Date'] || '',
      Notes: src.Notes || '',
      'Job URL': src['Job URL'],
      workerStatus: 'budget_reached',
    },
  }];
}
if (res.status === 'quota_reached') {
  return [{
    json: {
      row_number: src.row_number,
      company: src.Company,
      role: src.Role,
      Status: 'New',
      'Applied Date': src['Applied Date'] || '',
      Notes: src.Notes || '',
      'Job URL': src['Job URL'],
      workerStatus: 'quota_reached',
    },
  }];
}
const labels = { applied: 'Applied', agency_registered: 'Agency Registered', agency_job_referred: 'Agency Referred', closed: 'Closed', not_relevant: 'Not Relevant', no_suitable_replacement: 'Not Relevant', review: 'Review', failed: 'Review', invalid_url: 'Review', confirmation_not_detected: 'Review', already_submitted: 'Review', location_ineligible: 'Not Relevant', manual_required: 'Manual' };
const status = res.blocker === 'captcha' ? 'Manual' : (labels[res.status] || 'Review');
const notes = [res.notes || res.message || res.error || 'Worker returned no notes.', res.attemptId ? `attempt_id=${res.attemptId}` : ''].filter(Boolean).join('\n');
return [{
  json: {
    row_number: src.row_number,
    company: src.Company,
    role: src.Role,
    Status: status,
    'Applied Date': (status === 'Applied' || status === 'Agency Referred') ? (String(res.appliedAt || '').slice(0, 10) || today) : (src['Applied Date'] || ''),
    Notes: notes,
    'Job URL': res.canonicalJobUrl || src['Job URL'],
    workerStatus: res.status || 'failed',
  },
}];

const job = $('One Job').item.json;
const rowNumber = job.row_number;
if (rowNumber === undefined || rowNumber === null || rowNumber === '') {
  throw new Error(`Missing row_number for job ${job.Company || '?'} — ${job.Role || job['Job URL'] || 'no url'}`);
}
return [{
  json: {
    ...job,
    row_number: rowNumber,
    quota: $json,
  },
}];

const staticData = $getWorkflowStaticData('global');
const now = Date.now();
const DEBOUNCE_MS = 2 * 60 * 1000; // prevent double webhook / overlapping cron within 2 min
if (staticData.applyRunStartedAt && now - staticData.applyRunStartedAt < DEBOUNCE_MS) {
  throw new Error('Apply workflow started moments ago (debounce). Retry in 2 minutes.');
}
staticData.applyRunStartedAt = now;
return $input.all();

const companies = $('Load Exclude Companies').all()
  .map((item) => String(item.json.Company || item.json.company || '').trim())
  .filter(Boolean);
return [{ json: { companies, excludeCount: companies.length } }];

const staticData = $getWorkflowStaticData('global');
const RULE_VERSION = 1;
if (staticData.jobSheetManualHighlightRuleV === RULE_VERSION) {
  return [{ json: { skipped: true } }];
}
staticData.jobSheetManualHighlightRuleV = RULE_VERSION;
return [{ json: { skipped: false, spreadsheetId: 'YOUR_GOOGLE_SPREADSHEET_ID', sheetId: 0 } }];

